import{_ as e,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"正交解调","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/modules/quadrature_demod/index.md","filePath":"v0.4.0-alpha/modules/quadrature_demod/index.md"}'),r={name:"v0.4.0-alpha/modules/quadrature_demod/index.md"};function n(i,a,l,h,c,p){return t(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="正交解调" tabindex="-1">正交解调 <a class="header-anchor" href="#正交解调" aria-label="Permalink to &quot;正交解调&quot;">​</a></h1><p>适用：v0.4.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>quadrature_demod</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>从相邻复数样本的相位差得到实数解调值。设输入为 x，输出按 <code>gain×Arg(x[n]×conj(x[n−1]))</code> 计算；<code>conj</code> 表示共轭，<code>Arg</code> 取相位差的主值。</p><p>它适合观察复数信号的转动方向和速度，也可与调频器组成基础调制、解调实验。它本身不完成载波同步或码元定时恢复。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>调频.out → 正交解调.in → 二值判决.in</code>。先用观察器查看解调器的 <code>out</code>，再研究后续判决结果。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（复数输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>解调值；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>gain</code> 是相位差倍率，允许负值和 0，按有限 float32 值交给原生模块；实际值以原生回读为准。输出的单位标为<strong>解调值</strong>，不会因为连接了某个信号源就自动变成 Hz。</p><p>若要让数值对应频率 Hz，应按实际输入采样率设置 <code>gain = Fs/(2π)</code>。若要恢复调频器的输入，可在灵敏度 k 非零时选用 <code>gain = 1/k</code>。两种换算都要求相邻相位增量没有主值模糊；超过半周的转动无法仅靠相邻两点区分。输入幅度为零时，也没有可靠的相位差可供解释。</p><p>本模块只处理标量，采样率不变。原生模块使用前一个样本的历史；新准备后的首个输出为 0，N 个输入仍对应 N 个输出。首项占据正常的第一个时间位置，不应手动删掉或移动时间轴。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>相位差倍率<br><code>gain</code></td><td><code>1</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>gain</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线应用倍率后会回读实际值，并保留已有样本历史，只改变后续相位差的缩放。实际回执保留原生值，不把请求值当作逐样本生效边界。</p><p>停止后重新准备会重建历史，新一轮输出再次从首项 0 开始。编辑工程草稿与向当前任务在线应用是两个操作。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.4.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>调频与判决示例使用 4096 Hz 采样率，常量 1 经灵敏度 π/8 的调频器后，接入倍率 8/π 的正交解调器。选择 <code>out</code> 的时域输出，预期首项为 0，后续约为 1。</p><p>这个 1 表示按所选倍率恢复的输入值，不是 1 Hz。若改用 <code>Fs/(2π)</code> 的倍率，同一复数单音的稳态数值应约为 256；通道仍标为“解调值”。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么第一项比后面少一个值？</strong> 首项是原生历史初始化产生的 0，已经计入输出项数，不是丢样本。</p><p><strong>频率继续升高，解调值为什么反向或绕回？</strong> 相邻相位差只保留主值，可能已经发生混叠。检查实际 Fs 与每采样相位增量，不能靠增大 gain 消除这种模糊。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/08-fm/">08 从数值到调频再解调</a></li></ul>',34)])])}const b=e(r,[["render",n]]);export{u as __pageData,b as default};
